# =============================================================================
# Chapter 1 figures: Understanding Data through Measures and Visualizations
#
# Run from the project root:
#   Rscript r_code/figures/chapter_01.R
#
# Every plot uses the shared book theme and the Okabe-Ito palette. Captions and
# alt text live here, next to the code. figures/chapter_01/figures.yml is
# generated by save_book_fig(); do not edit it by hand.
#
# Figure 1.1 is a native table, not a plot, so it is not generated here.
# Figure 1.9 appears twice in the chapter. The mosaic plot keeps 1.9 and the
# GPA box plots use 1.9b. The prose still calls both "Figure 1.9".
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(readr)
  library(scales)
})

assert_book_font()

# ---- Data -------------------------------------------------------------------

sl <- read_csv(
  "data/student_lifestyle_sleep.csv", show_col_types = FALSE
) %>%
  mutate(
    DepressionStatus = factor(
      DepressionStatus,
      levels = c("normal", "moderate", "severe"),
      labels = c("Normal", "Moderate", "Severe")
    ),
    Stress = factor(
      Stress, levels = c("normal", "high"), labels = c("Normal", "High")
    ),
    AlcoholUse = factor(
      AlcoholUse, levels = c("Abstain", "Light", "Moderate", "Heavy")
    )
  )

n_students <- nrow(sl)

alcohol_cols <- c(
  Abstain  = book_palette[["sky_blue"]],
  Light    = book_palette[["orange"]],
  Moderate = book_palette[["bluish_green"]],
  Heavy    = book_palette[["vermillion"]]
)

stress_cols <- c(
  Normal = book_palette[["blue"]],
  High   = book_palette[["vermillion"]]
)

# ---- Figure 1.2: bar plot of depression status ------------------------------

dep_counts <- sl %>% count(DepressionStatus)

p12 <- ggplot(dep_counts, aes(x = DepressionStatus, y = n)) +
  geom_col(
    width = 0.62, fill = book_palette[["blue"]],
    colour = BOOK_INK, linewidth = 0.35
  ) +
  geom_text(
    aes(label = n), vjust = -0.45, size = 3.6, colour = BOOK_INK
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
  labs(x = "Depression status", y = "Number of students") +
  book_theme() +
  theme(panel.grid.major.x = element_blank())

save_book_fig(
  p12,
  chapter = 1, id = "1.2", type = "bar", slug = "depression_status",
  caption = "Depression screening status among 253 students, ordered from normal to severe.",
  alt = paste(
    "Bar chart of depression screening status for 253 students. The Normal",
    "bar is tallest at 209 students, Moderate is 34, and Severe is 10.",
    "Bars are ordered Normal, Moderate, Severe."
  ),
  direct_labels = TRUE
)

# ---- Figure 1.3: illustrative Pareto chart ----------------------------------

# No tutoring dataset exists. These counts are illustrative and match the
# chapter's description of the example. They are not reported as data.
tutoring_visits <- data.frame(
  Reason = factor(
    c("Math Help", "Computer Use", "Statistics Help",
      "Writing Help", "Other"),
    levels = c("Math Help", "Computer Use", "Statistics Help",
               "Writing Help", "Other")
  ),
  Visits = c(142, 96, 61, 48, 30)
)

p13 <- ggplot(tutoring_visits, aes(x = Reason, y = Visits)) +
  geom_col(
    width = 0.68, fill = book_palette[["blue"]],
    colour = BOOK_INK, linewidth = 0.35
  ) +
  geom_text(
    aes(label = Visits), vjust = -0.45, size = 3.4, colour = BOOK_INK
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
  labs(x = "Reason for visit", y = "Number of visits") +
  book_theme() +
  theme(
    panel.grid.major.x = element_blank(),
    axis.text.x = element_text(angle = 25, hjust = 1)
  )

save_book_fig(
  p13,
  chapter = 1, id = "1.3", type = "bar", slug = "pareto_tutoring",
  caption = "An illustrative Pareto chart of reasons for visiting a tutoring and STEM resource center.",
  alt = paste(
    "Pareto chart of illustrative tutoring and STEM center visits, sorted",
    "from most to least common. Math Help has the most visits, followed by",
    "Computer Use, Statistics Help, Writing Help, and Other, which combines",
    "the least common reasons."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "The tutoring counts are illustrative; no dataset exists for this",
    "example. Other combines the rare reasons so the chart stays readable.",
    "Replace with real data if the example becomes real."
  )
)

# ---- Figure 1.4: histogram of weekday sleep --------------------------------

p14 <- ggplot(sl, aes(x = WeekdaySleep)) +
  geom_histogram(
    binwidth = 1, boundary = 0, fill = book_palette[["sky_blue"]],
    colour = BOOK_INK, linewidth = 0.3
  ) +
  scale_x_continuous(breaks = 3:11) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(x = "Weekday sleep (hours)", y = "Number of students") +
  book_theme()

save_book_fig(
  p14,
  chapter = 1, id = "1.4", type = "hist", slug = "weekday_sleep",
  caption = "Distribution of weekday sleep hours for 253 students, binned in one-hour intervals.",
  alt = paste(
    "Histogram of weekday sleep hours in one-hour bins. The distribution is",
    "centered near 8 hours, with the tallest bins at 7 to 8 and 8 to 9 hours,",
    "and few students below 5 or above 10 hours."
  )
)

# ---- Figure 1.5: histogram with a normal curve -----------------------------

sleep_mean <- mean(sl$WeekdaySleep)
sleep_sd <- sd(sl$WeekdaySleep)

p15 <- ggplot(sl, aes(x = WeekdaySleep)) +
  geom_histogram(
    aes(y = after_stat(count)), binwidth = 1, boundary = 0,
    fill = book_palette[["sky_blue"]], colour = BOOK_INK, linewidth = 0.3
  ) +
  stat_function(
    aes(colour = "Normal curve"),
    fun = function(x) dnorm(x, sleep_mean, sleep_sd) * n_students,
    linewidth = 1, n = 300
  ) +
  scale_colour_manual(
    values = c("Normal curve" = book_palette[["vermillion"]]), name = NULL
  ) +
  scale_x_continuous(breaks = 3:11) +
  coord_cartesian(xlim = c(2.5, 11.5)) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(x = "Weekday sleep (hours)", y = "Number of students") +
  book_theme()

save_book_fig(
  p15,
  chapter = 1, id = "1.5", type = "hist", slug = "sleep_normal_overlay",
  caption = "Weekday sleep hours with a fitted normal curve. The histogram is roughly symmetric and centered near 8 hours.",
  alt = paste(
    "Histogram of weekday sleep hours with a smooth bell-shaped normal curve",
    "overlaid. The histogram is roughly symmetric, peaks at 7 to 9 hours, and",
    "the curve follows the same shape."
  ),
  direct_labels = TRUE
)

