# ---- Figure 1.13: IQR diagram ----------------------------------------------

p113 <- ggplot() +
  annotate(
    "rect", xmin = 2, xmax = 8, ymin = -0.5, ymax = 0.5,
    fill = "#DCE9F5", colour = BOOK_INK, linewidth = 0.7
  ) +
  annotate(
    "segment", x = 5, xend = 5, y = -0.5, yend = 0.5,
    colour = BOOK_INK, linewidth = 1.1
  ) +
  annotate(
    "segment", x = c(1, 8), xend = c(2, 9), y = 0, yend = 0,
    colour = BOOK_INK, linewidth = 0.7
  ) +
  annotate(
    "segment", x = c(1, 9), xend = c(1, 9), y = -0.25, yend = 0.25,
    colour = BOOK_INK, linewidth = 0.7
  ) +
  annotate(
    "text", x = c(2, 5, 8), y = -0.85,
    label = c("Q1 (25%)", "Median (50%)", "Q3 (75%)"),
    size = 3.6, colour = BOOK_INK
  ) +
  annotate(
    "segment", x = 2, xend = 8, y = 1.0, yend = 1.0,
    colour = BOOK_INK, linewidth = 0.5
  ) +
  annotate(
    "segment", x = c(2, 8), xend = c(2, 8), y = 0.9, yend = 1.1,
    colour = BOOK_INK, linewidth = 0.5
  ) +
  annotate(
    "text", x = 5, y = 1.35, label = "IQR = Q3 - Q1",
    size = 4.0, colour = BOOK_INK
  ) +
  coord_cartesian(xlim = c(0.4, 9.6), ylim = c(-1.2, 1.6), clip = "off") +
  theme_void(base_family = BOOK_FONT) +
  theme(
    plot.background = element_rect(fill = BOOK_BG, colour = NA),
    plot.margin = margin(10, 18, 10, 10)
  )

save_book_fig(
  p113,
  chapter = 1, id = "1.13", type = "diagram", slug = "iqr_boxplot",
  caption = "Quartiles and the interquartile range on a box plot.",
  alt = paste(
    "Diagram of a box plot. The left edge of the box is labeled Q1, the 25th",
    "percentile; the center line is the median, the 50th percentile; and the",
    "right edge is Q3, the 75th percentile. A bracket above the box spans Q1",
    "to Q3 and is labeled IQR equals Q3 minus Q1."
  ),
  direct_labels = TRUE
)

